{
  "decision-stage-a-reserve-trailer-for-worst-case-response": "SELECT q.yard_id, max(q.mill_min, q.vale_min) AS worst_minutes, q.mill_min * b.mill_calls + q.vale_min * b.vale_calls AS forecast_minutes, q.source_id AS quote_source, b.source_id AS brief_source FROM yard_quote AS q CROSS JOIN shift_brief AS b WHERE q.fee_cents <= b.budget_cents ORDER BY worst_minutes, forecast_minutes, q.yard_id COLLATE BINARY LIMIT 1",
  "decision-stage-installation-crew-upgrade": "SELECT o.offer_id, (p.base_hours - o.base_cut) + max(p.light_hours - o.light_cut, p.deck_hours - o.deck_cut) + (p.inspect_hours - o.inspect_cut) AS finish_hour, o.fee_cents FROM crew_offer AS o CROSS JOIN rig_plan AS p WHERE o.fee_cents <= p.budget_cents ORDER BY finish_hour, o.fee_cents, o.offer_id COLLATE BINARY LIMIT 1",
  "decision-standing-exchange-disqualifications": "WITH eligible AS (SELECT squad, incident_no, verdict, source_id, primary_text, row_number() OVER (PARTITION BY meet_code, squad, incident_no ORDER BY bulletin_no DESC) AS decision_rank FROM ruling WHERE meet_code = 'Copper' AND bulletin_no <= 4) SELECT squad, incident_no, source_id, primary_text FROM eligible WHERE decision_rank = 1 AND verdict = 'dq' ORDER BY squad, incident_no",
  "decision-station-bias-with-fixed-effects": "WITH centered AS (SELECT confidence, test_mode - sum(1.0 * confidence * test_mode) OVER w / sum(1.0 * confidence) OVER w AS dx, reading_mm - sum(1.0 * confidence * reading_mm) OVER w / sum(1.0 * confidence) OVER w AS dy FROM station_readings WINDOW w AS (PARTITION BY station)) SELECT round(sum(confidence * dx * dy) / sum(confidence * dx * dx), 3) AS bias_mm FROM centered"
}
